entries[169899] = { ["name"] = "Polierte Schädeltrophäe", ["text"] = "Rang 4\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Konflikt und Zwietracht'.\nGroße Macht:\nKonflikt\nLehrt Euch das PvP-Talent ' ' und ermöglicht den Einsatz gegen alle Gegner Azeroths.\n\nWährend Ihr betäubt seid, ist der defensive Bonus Eurer Vielseitigkeit um 50% erhöht.\n\nBannen, Unterbrechen oder Anwenden von Gruppenkontrolleffekten gewährt einen Stapel von 'Zwietracht'. Die durch 'Zwietracht' gewährte Vielseitigkeit wird für die nächsten 5 Sek. verdoppelt.\nGeringe Macht:\nZwietracht\nEure Zauber und Fähigkeiten haben eine Chance, Eure Vielseitigkeit 14 Sek. lang um 11 zu erhöhen. Bis zu 8-mal stapelbar. Wenn Ihr Opfer eines bewegungseinschränkenden oder Gruppenkontrolleffekts werdet, erhaltet Ihr ebenfalls einen Stapel von 'Zwietracht'." }
entries[169900] = { ["name"] = "Rippenknochenhalsreif der Vorherrschaft", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Konflikt und Zwietracht'.\nIhr müsst in der Vorwoche eine PvP-Wertung von 1.400 oder höher erreicht haben.\nErlernt mit einem anderen Charakter 'Rang 3 - Konflikt und Zwietracht', um diese Essenz freizuschalten.\nGroße Macht:\nKonflikt\nLehrt Euch das PvP-Talent ' ' und ermöglicht den Einsatz gegen alle Gegner Azeroths.\n\nWährend Ihr betäubt seid, ist der defensive Bonus Eurer Vielseitigkeit um 50% erhöht.\n\nBannen, Unterbrechen oder Anwenden von Gruppenkontrolleffekten gewährt einen Stapel von 'Zwietracht'. Die durch 'Zwietracht' gewährte Vielseitigkeit wird für die nächsten 5 Sek. verdoppelt.\nGeringe Macht:\nZwietracht\nEure Zauber und Fähigkeiten haben eine Chance, Eure Vielseitigkeit 14 Sek. lang um 11 zu erhöhen. Bis zu 8-mal stapelbar. Wenn Ihr Opfer eines bewegungseinschränkenden oder Gruppenkontrolleffekts werdet, erhaltet Ihr ebenfalls einen Stapel von 'Zwietracht'." }
entries[169901] = { ["name"] = "Geätzte Knochentrophäe der Bezwungenen", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht Eurem Herz von Azeroth 'Konflikt und Zwietracht'.\nIhr müsst in der Vorwoche eine PvP-Wertung von 1.000 oder höher erreicht haben.\nGroße Macht:\nKonflikt\nLehrt Euch das PvP-Talent ' ' und ermöglicht den Einsatz gegen alle Gegner Azeroths.\n\nWährend Ihr betäubt seid, ist der defensive Bonus Eurer Vielseitigkeit um 50% erhöht.\nGeringe Macht:\nZwietracht\nEure Zauber und Fähigkeiten haben eine Chance, Eure Vielseitigkeit 14 Sek. lang um 11 zu erhöhen. Bis zu 5-mal stapelbar. Wenn Ihr Opfer eines bewegungseinschränkenden oder Gruppenkontrolleffekts werdet, erhaltet Ihr ebenfalls einen Stapel von 'Zwietracht'." }
