entries[170069] = { ["name"] = "Harnisch der Honigrückenernterin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Allianz-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Während die meisten Ernterinnen nur von Honig und Blüten träumen, interessiert sich dieses abenteuerlustige Exemplar für die weite Welt jenseits des Sturmsangtals.\"\nQuest:\nDen Stock verlassen: Ernterin\nZone:\nDas Sturmsangtal" }
