entries[170171] = { ["name"] = "Riesenkrabbenbein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Sieht saftig aus. Vielleicht kann einer Eurer neuen Verbündeten in Nazjatar damit etwas anfangen.\"" }
entries[170172] = { ["name"] = "Glanzstachelmuschel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt Euch die glänzende, stachelige Muschel auf den Kopf. Sie fügt Gegnern, die Euch im Nahkampf angreifen, körperlichen Schaden zu, erhöht aber den Radius, in dem Gegner Euch entdecken.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n4 Aufladungen\n\"Die Muschel glitzert im Sonnenlicht.\"\nVerkaufspreis:" }
entries[170173] = { ["name"] = "Glyphe 'Killerbienen'", ["text"] = "Klassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Einsatz Eurer Fähigkeit 'Alphatier' ruft Bienen herbei! KILLERBIENEN!!! Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel'\nVerkaufspreis:" }
entries[170174] = { ["name"] = "Schlammschleim", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht 20 Min. lang die Ausweichchance um 35% und gewährt erhöhtes Tempo, wenn Ihr einem Angriff ausweicht.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (1s Abklingzeit) (10 Sek. Abklingzeit)\n\"Wirkt ganz besonders schleimig.\"\nVerkaufspreis:" }
entries[170175] = { ["name"] = "Technik: Glyphe 'Killerbienen'", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man die Glyphe 'Killerbienen' schreibt.\nBenötigt Inschriftenkunde von Kul Tiras (150)\nVerkaufspreis:\nGlyphe 'Killerbienen'\nKlassen: Jäger\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nDer Einsatz Eurer Fähigkeit 'Alphatier' ruft Bienen herbei! KILLERBIENEN!!! Exklusiv mit: Glyphe 'Arachnophobie' Glyphe 'Nesingwarys Nemesis' Glyphe 'Alpharudel'\nVerkaufspreis:\nBenötigt Leichtes Pergament , Blutrote Tinte (10), Chorhonig (10), Ultramarinblaue Tinte (30)" }
entries[170176] = { ["name"] = "Tiefenrochenflügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das harte, gummiartige Äußere schützt das zarte Fleisch darin. Vielleicht kann einer Eurer neuen Verbündeten in Nazjatar damit etwas anfangen.\"" }
entries[170177] = { ["name"] = "Gestrandeter Fisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Legt den Fisch auf den Boden und befördert ihn mit Tritten durch die Gegend. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170178] = { ["name"] = "Alphafinne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Beschwört einen reitbaren wilden Schnappdrachen für 20 Sek. Wenn Ihr absteigt, kämpft der Schnappdrache 1 Min. lang für Euch. Das ist ein sehr, SEHR schnelles Reittier.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170179] = { ["name"] = "Schnappdrachenduftdrüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Zerquetscht die Drüse, werdet zum Rudelführer und beschwört so Schnappdrachen, die 1 Min. lang für Euch kämpfen.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n\"Die Drüse einer Schnappdrachenmatriarchin oder eines -patriarchen weist den Besitzer als Rudelführer aus.\"\nVerkaufspreis:" }
entries[170180] = { ["name"] = "Klingenpanzer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört für 5 Min. einen reitbaren Panzer, der gegnerische Spielercharaktere zum Absteigen zwingt und sie betäubt.\n\nKann nur im Kriegsmodus in Mechagon, Nazjatar, Zandalar und Kul Tiras verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170181] = { ["name"] = "Gezeitenschutz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Gezeitenwächter, der Euch 2 Min. lang beisteht.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170182] = { ["name"] = "Voltschuppenschild", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Trifft Gegner in der Nähe mit Gezeitenwächterblitzen, die Naturschaden verursachen und den erlittenen Naturschaden erhöhen.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n10 Aufladungen\nVerkaufspreis:" }
entries[170183] = { ["name"] = "Riffwandererborke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Hart, aber saugfähig. Vielleicht kann einer Eurer neuen Verbündeten in Nazjatar damit etwas anfangen.\"" }
entries[170184] = { ["name"] = "Uralte Riffwandererborke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine äußerst widerstandsfähige, aber schwammige Substanz. Vielleicht kann einer Eurer neuen Verbündeten in Nazjatar damit etwas anfangen.\"" }
entries[170185] = { ["name"] = "Intaktes Nagaskelett", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Der Naga wurde wahrscheinlich im Ganzen verschlungen und scheint etwas zu umklammern.\"\n<Zum Öffnen rechtsklicken>" }
entries[170186] = { ["name"] = "Abgrundperle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Platziert eine Perle aus den Tiefen. Gewährt Spielercharakteren in der Nähe Meisterschaft, während sie sich in Nazjatar befinden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170187] = { ["name"] = "Schattenschuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ergreift die Schatten um die Schuppe und erlebt die Welt, als ob es Mitternacht wäre. (1 Stunde Abklingzeit)\n\"Die Schuppe in den Händen zu halten umwölkt Euren Blick mit einer jenseitigen Nacht.\"" }
entries[170188] = { ["name"] = "Muschelverkrusteter Beutel mit Gütern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[170189] = { ["name"] = "Blindes Auge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das Auge kann für ein hübsches Sümmchen an die richtige Person verkauft werden, aber Ihr fühlt Euch schon unbehaglich, wenn Ihr es nur in der Hand haltet.\"" }
entries[170190] = { ["name"] = "Mardivas' Beutel des Enthaltens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[170191] = { ["name"] = "Skeletthand", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine belebte Skeletthand. Sie wird ein hübsches Sümmchen einbringen, wenn sie an den richtigen Händler verkauft wird, aber sie ist mit Sicherheit verflucht.\"" }
entries[170192] = { ["name"] = "Schlammwickel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Hüllt Euch in verjüngenden Schlamm, der Euch heilt und 15 Sek. lang alle 3 Sek. einen Fluch-, Krankheits-, Magie- oder Blutungseffekt entfernt.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n5 Aufladungen\n\"Der warme Schlamm belebt Haut und Seele.\"\nVerkaufspreis:" }
entries[170193] = { ["name"] = "Meerestotem", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen Meereselementar, der Euch 1 Min. lang im Kampf beisteht.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170194] = { ["name"] = "Totem des Sturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Sturmelementar, der Euch 1 Min. lang im Kampf beisteht.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[170195] = { ["name"] = "Vorratstasche des Leerenwirkers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[170196] = { ["name"] = "Warnschild der Shirakess", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (1 Stunde Abklingzeit)" }
entries[170197] = { ["name"] = "Dunkles Warnschild", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Platziert ein Warnschild, was 1 Min. lang bestehen bleibt. In das Schild kann eine Nachricht geschnitzt werden, wodurch es 1 Stunde bestehen bleibt und für andere Spielercharaktere sichtbar wird. (1 Stunde Abklingzeit)" }
entries[170198] = { ["name"] = "Essgeschirr des Ewigen Palasts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Trifft Vorbereitungen für das Abendessen. (2 Std. Abklingzeit)" }
entries[170199] = { ["name"] = "Waffenständer der Zanj'ir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Rüstet eine Nagawaffe aus. (2 Std. Abklingzeit)" }
entries[170200] = { ["name"] = "Seesturmtotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Seesturmelementar, der Euch 1 Min. lang im Kampf beisteht.\n\nKann nur in Kul Tiras, Zandalar und Nazjatar verwendet werden. (10 Sek. Abklingzeit)\n2 Aufladungen\nVerkaufspreis:" }
entries[170201] = { ["name"] = "Tiefenflutschriftrolle", ["text"] = "Wird beim Anlegen gebunden\nIn Schildhand geführt\n+10 Intelligenz\n+5 Ausdauer\nVerkaufspreis:" }
entries[170202] = { ["name"] = "Shwayderbräu", ["text"] = "Benutzen: Ein typisches alkoholisches Getränk.\nBenötigt Braufest\n\"Das Markenbier des berühmten Braumeisters der Dunkeleisenzwerge Schwarzwache Shwayder.\"\nVerkaufspreis:" }
entries[170203] = { ["name"] = "Zappelnder Fisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Legt den Fisch auf den Boden und befördert ihn mit Tritten durch die Gegend. (1 Stunde Abklingzeit)" }
entries[170204] = { ["name"] = "Symbol des Gral", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Glaubt an Gral und seid gesegnet. (2 Std. Abklingzeit)\n\"Je mehr das Symbol des Gral tragen, desto stärker wird die Präsenz des Verlorenen.\"" }
entries[170205] = { ["name"] = "Krone des grenzenlosen Mutes", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Ein Blumenkranz, der seinem Träger ein Jahr voller Mut bescheren soll.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[170206] = { ["name"] = "Krone des unendlichen Wohlstands", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Ein Blumenkranz, der seinem Träger ein Jahr voller Wohlstand bescheren soll.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[170207] = { ["name"] = "Krone des ewigen Andenkens", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Ein Blumenkranz, der seinem Träger ein Jahr voller feierlichem Ernst bescheren soll.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[170208] = { ["name"] = "Rezept: Trank der ungezügelten Wut", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der ungezügelten Wut effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nVerkaufspreis:\nTrank der ungezügelten Wut\nBenutzen: Verleiht Euch selbst ungezügelte Energie und gewährt Euren offensiven Zaubern und Angriffen eine Chance, Eurem Ziel zusätzlich 1344 Feuerschaden zuzufügen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (6), Kristallphiole" }
entries[170209] = { ["name"] = "Rezept: Trank der wilden Heilung", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der wilden Heilung effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nVerkaufspreis:\nTrank der wilden Heilung\nBenutzen: Ermächtigt Euren Verstand und gewährt Euren Heilfähigkeiten eine Chance, bei Eurem Ziel zusätzlich 2017 Gesundheit wiederherzustellen. Hält 1 Min. lang an. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (6), Kristallphiole" }
entries[170210] = { ["name"] = "Rezept: Abyssischer Heiltrank", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen abyssischen Heiltrank effizienter herstellt.\nChance auf die Herstellung mehrerer Tränke.\nBenötigt Alchemie von Kul Tiras\n(170)\nVerkaufspreis:\nAbyssischer Heiltrank\nBenutzen: Stellt 16000 Gesundheit wieder her. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zin'anthide (2), Kristallphiole" }
entries[170211] = { ["name"] = "Bauplan: FastenEvaluationsSystem mit TischMahlzeiten und Appetitlichen Heißen Leckereien", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein FastenEvaluationsSystem mit TischMahlzeiten und Appetitlichen Heißen Leckereien effizienter herstellt.\nVerbraucht deutlich weniger Zutaten bei der Zubereitung von einem F.E.S.T.M.A.H.L.\nBenötigt Kochkunst von Kul Tiras (175)\nVerkaufspreis:\nFastenEvaluationsSystem mit TischMahlzeiten und Appetitlichen Heißen Leckereien\nBenutzen: Richtet ein F.E.S.T.M.A.H.L. her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 50769 Gesundheit und 30769 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 50 erhöht.\nVerkaufspreis:\nBenötigt Vipernfisch (15), Ionisierte Elritze (15), Zähe Lende (15), Fleischige Keule (15), Frische Kartoffel (20), Kiste mit E.R.S.A.T.Z.-Teilen" }
entries[170212] = { ["name"] = "Rezept: Mechabytes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Mechabytes zubereitet.\nBereitet Mechabytes zu.\nBenötigt Kochkunst von Kul Tiras (150)\nVerkaufspreis:\nMechabytes\nBenutzen: Esst mich?\n\"Nur für kurze Zeit: Jetzt mit rostiger Zahnscheibe zum Sammeln, Verschlucken und Tauschen!\"\nVerkaufspreis:\nBenötigt Ersatzteile (25)" }
entries[170213] = { ["name"] = "Formel: Nagahaut", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man 'Nagahaut' effizienter herstellt.\nEine Waffe dauerhaft mit einem Schutzzauber der Naga verzaubern, sodass beim Blocken, Ausweichen oder Parieren eine Chance besteht, Eure Stärke oder Beweglichkeit 15 Sek. lang um 4 zu erhöhen. Während der Effekt aktiv ist, ist Eure Haut außerdem von dicken Schuppen überzogen, durch die Ihr 1573 Schaden absorbiert. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\n\nMaterialbedarf erheblich verringert.\nBenötigt Verzauberkunst von Kul Tiras (175)\nVerkaufspreis:" }
entries[170250] = { ["name"] = "Waffentruhe der Eidgebundenen", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt eine Waffe für Eure Beutespezialisierung.\"" }
entries[170251] = { ["name"] = "Waffentruhe der 7. Legion", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt eine Waffe für Eure Beutespezialisierung.\"" }
entries[170252] = { ["name"] = "Beutel mit Wundbrandsporen", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Ihr werft Wundbrandsporen auf einen Gegner, die diesem 15 Sek. lang alle 3 Sek. 3506 Naturschaden zufügen.\n\nKann nur auf Inselexpeditionen verwendet werden. (2 Min Abklingzeit)" }
entries[170253] = { ["name"] = "Vergifteter Schleifstein", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Eure Angriffe haben eine Chance, dem Ziel 12 Sek. lang alle 3 Sek. 931 Naturschaden zuzufügen.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170255] = { ["name"] = "Kräuterkundigenset der Pandaren", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht sämtliche erhaltene Heilung um 120 Gesundheit. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170256] = { ["name"] = "Söldnerset der Shado-Pan", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht den Schaden, den Ihr Mogu- oder Mantisgegnern zufügt, um 5%. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170257] = { ["name"] = "Spiegel der Zauberumkehr", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Ihr von einem Zauber getroffen werdet, wird Euer Schaden 25 Sek. lang um 8% erhöht. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170258] = { ["name"] = "Rute der magischen Inbrunst", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Ihr einen gegnerischen Zauberwirker besiegt, wird Eure Hauptwert 15 Sek. lang um 192 erhöht. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170259] = { ["name"] = "Foliant der letzten Ölung", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Ihr einen Furbolg, Druiden oder Hüter tötet, wird Eure Ausdauer 20 Sek. lang um 240 erhöht. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170260] = { ["name"] = "Gebetsperlen der Bestattung", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Ihr einen Furbolg, Druiden oder Hüter tötet, wird Eure Ausdauer 20 Sek. lang um 240 erhöht. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170261] = { ["name"] = "Foliant des natürlichen Gleichgewichts", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht den Schaden gegen Tiere um 5%. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170262] = { ["name"] = "Totem der jährlichen Dezimierung", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht den Schaden gegen Tiere um 5%. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170263] = { ["name"] = "Wasserdichtes Kafafläschchen", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht Eure Geschwindigkeit 20 Sek. lang um 156 .\n\nKann nur auf Inselexpeditionen verwendet werden. (2 Min Abklingzeit)" }
entries[170264] = { ["name"] = "Fernrohr des Meeresfluchs", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht Euren Schaden gegen Naga, Kvaldir und Piraten um 5%. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170265] = { ["name"] = "Verbesserter Bergbaubohrer", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Erhöht die Geschwindigkeit, mit der Ihr Azerit aus Erzadern und Mineralvorkommen abbaut. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170266] = { ["name"] = "Kampf-oder-Flucht-Verstärker", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Eure Gesundheit unter 30% sinkt, erhaltet Ihr 20 Sek. lang 72 Geschwindigkeit. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (1 Min Abklingzeit)" }
entries[170267] = { ["name"] = "Muskelinfusor der Blutwitterung", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (3)\nBenutzen: Wenn Ihr einen Gegner besiegt, wird Eure Geschwindigkeit 12 Sek. lang um 72 erhöht. Hält 20 Min. lang an.\n\nKann nur auf Inselexpeditionen verwendet werden. (30s Abklingzeit) (1 Min Abklingzeit)" }
