entries[170543] = { ["name"] = "Merkwürdiger Stein", ["text"] = "Questgegenstand\nEinzigartig\n\"Der Stein summt leise, als ob er lebendig wäre.\"" }
entries[170547] = { ["name"] = "Mardivas' Schlüssel der arkanen Truhe", ["text"] = "Questgegenstand\n\"Wäre der Schlüssel nicht verzaubert, hätte der Rost ihn schon lange zerfressen.\"" }
entries[170549] = { ["name"] = "Erste-Hilfe-Kasten", ["text"] = "Questgegenstand\n\"Es hat etwas Wasserschaden abbekommen, aber die Vorräte in diesem Set sind besser als nichts.\"" }
entries[170550] = { ["name"] = "Heilige Schriftrolle", ["text"] = "Questgegenstand\n\"Teil einer Reihe über einen mächtigen Ritus der Demut.\"" }
entries[170551] = { ["name"] = "Licht der Bastion", ["text"] = "Questgegenstand\n\"Ein strahlendes Licht, das Eurer Seele den Weg nach Hause leuchtet, ganz gleich, wo Ihr seid.\"" }
entries[170552] = { ["name"] = "Nekrotischer Fetisch", ["text"] = "Questgegenstand\n\"Aus diesem Fetisch triefen nekrotische Energien. Man transportiert ihn am besten in einer versiegelten Tasche.\"" }
entries[170553] = { ["name"] = "Leerenfokussplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\n\"Bei den Gesichtslosen, K'thir, Aqir und Kultisten im Dienste von N'Zoth zu finden.\"" }
entries[170554] = { ["name"] = "Wachtfackel", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[170557] = { ["name"] = "Größenänderer v9.0.1", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Vergrößert eine Kreatur. Funktioniert nicht unbedingt. Jagt den Benutzer nicht in die Luft. (8 Sek. Abklingzeit)" }
entries[170585] = { ["name"] = "Erschöpfter Animakern", ["text"] = "Questgegenstand\n\"Es sieht leider so aus, als ob alle Anima komplett entzogen wurde.\"" }
entries[170586] = { ["name"] = "Pläne: Bogen des unheimlichen Kämpfers", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Bogen des unheimlichen Kämpfers effizienter herstellt.\nVerringert die erforderlichen Materialien zur Herstellung eines Bogens des unheimlichen Kämpfers.\nBenötigt Lederverarbeitung von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nBogen des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Bogen\n13 - 18 Schaden Geschwindigkeit 3.00\n(5.2 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nHorde\nBogen des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Bogen\n13 - 18 Schaden Geschwindigkeit 3.00\n(5.2 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Sedimentleder (23), Klippenschuppe (23), Blutbefleckter Knochen (30), Expulsom (6)" }
entries[170587] = { ["name"] = "Pläne: Bogen des unheimlichen Kämpfers", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Bogen des unheimlichen Kämpfers effizienter herstellt.\nVerringert erheblich die erforderlichen Materialien zur Herstellung eines Bogens des unheimlichen Kämpfers.\nBenötigt Lederverarbeitung von Kul Tiras (1)\nVerkaufspreis:\nAllianz\nBogen des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Bogen\n13 - 18 Schaden Geschwindigkeit 3.00\n(5.2 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nHorde\nBogen des unheimlichen Kämpfers\nWird beim Anlegen gebunden\nDistanz Bogen\n13 - 18 Schaden Geschwindigkeit 3.00\n(5.2 Schaden pro Sekunde)\n+7 Beweglichkeit\n+10 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Sedimentleder (20), Klippenschuppe (20), Blutbefleckter Knochen (25), Expulsom (5)" }
